def check(expr):
    ids = {t for t in expr.replace('(', ' ').replace(')', ' ').split() if t not in ('OR', 'AND', 'WITH')}
    unknown = ids - SPDX - {'Classpath-exception'}
    return 'OK' if not unknown else 'REVIEW: unknown %s' % unknown

for e in ['MIT', '(MIT OR Apache-2.0)', 'GPL-3.0-only', 'CustomCorp-1.0']:
    print('%-28s %s' % (e, check(e)))
