# transitive closure: the deps you didn't choose still ship
# app -> lib-a -> lib-b -> lib-c(GPL)
graph = {'app': ['lib-a'], 'lib-a': ['lib-b'], 'lib-b': ['lib-c'], 'lib-c': []}
licenses = {'lib-a': 'MIT', 'lib-b': 'Apache-2.0', 'lib-c': 'GPL-3.0-only'}

seen, stack = set(), ['app']
while stack:
    n = stack.pop()
    for d in graph[n]:
        if d not in seen:
            seen.add(d)
            stack.append(d)
print('direct deps: 1 | transitive: %d' % len(seen))
for d in sorted(seen):
    print('  %-8s %s %s' % (d, licenses[d], '<- surfaced by scanning' if 'GPL' in licenses[d] else ''))

# policy as code: rules evaluated per component, verdicts cited
POLICY = [
    ('deny', {'GPL-3.0-only', 'AGPL-3.0-only'}, 'copyleft banned in shipped products'),
    ('allow', {'MIT', 'Apache-2.0', 'BSD-3-Clause', 'ISC'}, 'permissive: fine'),
]

def verdict(lic):
    for action, licenses, reason in POLICY:
        if lic in licenses:
            return action.upper(), reason
    return 'REVIEW', 'unknown license: legal must decide'

for lic in ['MIT', 'GPL-3.0-only', 'CustomCorp-1.0']:
    v, why = verdict(lic)
    print('%-16s %-6s (%s)' % (lic, v, why))

