import hashlib

# fingerprint DB: known release hashes
KNOWN = {hashlib.md5(b'lib v1.0').hexdigest()[:8]: ('cool-lib', '1.0', 'MIT')}

vendored = {'vendor/cool/': b'lib v1.0', 'vendor/mystery/': b'??? unknown blob'}
for path, content in vendored.items():
    fp = hashlib.md5(content).hexdigest()[:8]
    hit = KNOWN.get(fp)
    print('%-16s -> %s' % (path, '%s %s (%s)' % hit if hit else 'UNKNOWN: identify or remove'))
print('vendored != invisible: fingerprint it, license it, review new additions')

from collections import deque
queue = deque()

def triage(dep, lic):
    if lic in ('MIT', 'Apache-2.0', 'BSD-3-Clause'):
        return 'auto-allow'
    if 'GPL' in lic:
        return 'auto-deny (policy)'
    queue.append((dep, lic))
    return 'queued for legal (SLA 48h)'

for dep, lic in [('a', 'MIT'), ('b', 'GPL-3.0-only'), ('c', 'CustomCorp-1.0')]:
    print('%-4s %-16s -> %s' % (dep, lic, triage(dep, lic)))
print('queue depth:', len(queue), '| decisions feed back into policy')

# alert on license CHANGES, not just violations
prev = {'lib-x': 'MIT', 'lib-y': 'Apache-2.0'}
cur = {'lib-x': 'SSPL-1.0', 'lib-y': 'Apache-2.0', 'lib-z': 'GPL-3.0-only'}

for dep, lic in cur.items():
    if dep not in prev:
        print('NEW dep %s (%s): policy check required' % (dep, lic))
    elif prev[dep] != lic:
        print('ALERT: %s relicensed %s -> %s (the SSPL wave pattern)' % (dep, prev[dep], lic))
print('the audit is a process: diff every resolved graph, alert on change')
